17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Map;
20	import java.util.Optional;
21	
22	/**
23	 * Decides whether a 4-digit postcode is valid for a city, and reverse-maps a postcode
24	 * to its region, using a fixed table of inclusive postcode ranges keyed by region
25	 * (as resolved by {@link LocalityResolver}). A city whose region is unknown accepts any
26	 * 4-digit postcode.
27	 */
28	public final class PostcodePolicy {
29	
30	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
31	        "NSW", new int[] {2000, 2099},
32	        "VIC", new int[] {3000, 3099},
33	        "QLD", new int[] {4000, 4099});
34	
35	    private PostcodePolicy() {
36	    }
37	
38	    /**
39	     * Check whether the given 4-digit postcode falls within the range allowed for the
40	     * city's region.
41	     *
42	     * @param city the owner's city, may be {@code null}
43	     * @param postcode a 4-digit postcode string
44	     * @return {@code true} when the city's region is unknown, or the postcode is within
45	     * the region's inclusive range; {@code false} otherwise
46	     */
47	    public static boolean isValidForCity(String city, String postcode) {
48	        int[] range = REGION_POSTCODE_RANGE.get(LocalityResolver.regionForCity(city));
49	        if (range == null) {
50	            return true;
51	        }
52	        return inRange(Integer.parseInt(postcode), range);
53	    }
54	
55	    /**
56	     * Reverse-map a postcode to the region whose range contains it.
57	     *
58	     * @param postcode a postcode string, may be {@code null} or non-numeric
59	     * @return the matching region, or {@link Optional#empty()} when the postcode is
60	     * absent, non-numeric, or in no known range
61	     */
62	    public static Optional<String> regionForPostcode(String postcode) {
63	        if (postcode == null) {
64	            return Optional.empty();
65	        }
66	        int value;
67	        try {
68	            value = Integer.parseInt(postcode.trim());
69	        }
70	        catch (NumberFormatException ex) {
71	            return Optional.empty();
72	        }
73	        return REGION_POSTCODE_RANGE.entrySet().stream()
74	            .filter(entry -> inRange(value, entry.getValue()))
75	            .map(Map.Entry::getKey)
76	            .findFirst();
77	    }
78	
79	    private static boolean inRange(int value, int[] range) {
80	        return value >= range[0] && value <= range[1];
81	    }
82	}
