17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	
23	/**
24	 * Derives the stable {@code householdId} shared by owners that live in the same household,
25	 * i.e. that have the same last name and address. The identifier is a deterministic function
26	 * of those two values (compared case- and whitespace-insensitively via {@link TextNormalizer}),
27	 * so every member of a household independently derives the same identifier regardless of the
28	 * order in which they are created.
29	 */
30	public final class HouseholdIdGenerator {
31	
32	    /** Number of hex characters kept from the digest; ample to avoid realistic collisions. */
33	    private static final int LENGTH = 12;
34	
35	    private HouseholdIdGenerator() {
36	    }
37	
38	    /**
39	     * Compute the stable household identifier for the given last name and address.
40	     *
41	     * @param lastName the household's last name
42	     * @param address  the household's address
43	     * @return an upper-case hex identifier that is identical for any two owners whose last name
44	     * and address normalize to the same values
45	     */
46	    public static String generate(String lastName, String address) {
47	        String key = TextNormalizer.normalize(lastName) + "\n" + TextNormalizer.normalize(address);
48	        return shaHex(key).substring(0, LENGTH).toUpperCase();
49	    }
50	
51	    private static String shaHex(String value) {
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
54	            StringBuilder sb = new StringBuilder(digest.length * 2);
55	            for (byte b : digest) {
56	                sb.append(String.format("%02x", b));
57	            }
58	            return sb.toString();
59	        } catch (NoSuchAlgorithmException e) {
60	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
61	        }
62	    }
63	}
