public static Integer compute(String value) {
    if (value == null) {
        return null;
    }
    int sum = 0;
    boolean doubleDigit = true;
    for (int i = value.length() - 1; i >= 0; i--) {
        char c = value.charAt(i);
        if (c < '0' || c > '9') {
