19	import java.time.LocalDate;
20	
21	/**
22	 * Builds an owner's {@code membershipNumber} from their customer code and registration date.
23	 */
24	public final class MembershipNumberFormatter {
25	
26	    private MembershipNumberFormatter() {
27	    }
28	
29	    /**
30	     * Format a membership number as {@code "<customerCode>-M<YY>"}, where {@code YY} is the last
31	     * two digits of the registration date's year, zero-padded (for example {@code "SMI-0007-M26"}).
32	     *
33	     * @param customerCode     the owner's customer code
34	     * @param registrationDate the owner's registration date
35	     * @return the formatted membership number, or {@code null} if either input is {@code null}
36	     */
37	    public static String format(String customerCode, LocalDate registrationDate) {
38	        if (customerCode == null || registrationDate == null) {
39	            return null;
40	        }
41	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
42	    }
43	}
